INSERT IGNORE INTO `broadcast_text_locale` (`ID`,`locale`,`Text_lang`,`Text1_lang`,`VerifiedBuild`) VALUES
(212752,'ruRU','Знание может быть как инструментом, так и оружием.','Знание может быть как инструментом, так и оружием.',70338),
(290402,'ruRU','Хоть ты и не паладин, но если пожелаешь, то еще можешь найти утешение у Света.','Хоть ты и не паладин, но если пожелаешь, то еще можешь найти утешение у Света.',70338),
(292961,'ruRU','Профессии делятся на две главные категории: основные и вспомогательные.\r\n\r\nМожно получить только две основные профессии. В любой момент разрешено отказаться от одной из профессий, но все полученные знания при этом будут утрачены. Если же вернуться к забытой профессии, придется изучать все с нуля и собирать рецепты повторно.\r\n\r\nУ вспомогательных профессий нет такого ограничения. Цель этих навыков – основы выживания без чужой помощи. Все вспомогательные профессии можно прокачивать одновременно, но они почти не будут приносить прибыли.','Профессии делятся на две главные категории: основные и вспомогательные.\r\n\r\nМожно получить только две основные профессии. В любой момент разрешено отказаться от одной из профессий, но все полученные знания при этом будут утрачены. Если же вернуться к забытой профессии, придется изучать все с нуля и собирать рецепты повторно.\r\n\r\nУ вспомогательных профессий нет такого ограничения. Цель этих навыков – основы выживания без чужой помощи. Все вспомогательные профессии можно прокачивать одновременно, но они почти не будут приносить прибыли.',70425),
(296872,'ruRU','Что брату Пакстону нужно на этот раз?','Что брату Пакстону нужно на этот раз?',70338),
(299774,'ruRU','<Подойдя к громадному циклонному голему, вы слышите тихое жужжание из-под его массивных доспехов. Если прислушаться повнимательнее, можно разобрать несколько осмысленных слогов, но искаженный звук мешает понять слова.>','<As you approach the enormous cyclone construct, you hear a faint buzzing emanating from beneath its massive armor plates. If you listen carefully, you think you might be able to hear a few words being formed but they are too distorted to make out.>',70338),
(299873,'ruRU','','Здравствуй, |3-6($c).',70338),
(300037,'ruRU','П-привет. Не обижайся, пожалуйста. Ваши обычно от меня убегают.','',70338),
(300039,'ruRU','That is... a very good question. I have a hard time remembering things, but I do remember something... "Engineer", perhaps? I think that\'s what, or who, I was.\r\n\r\nOther than that, all I can seem to remember is soaring through the sky, then seeing a flash of lightning before things got very bumpy. Then... a crash.\r\n\r\nIt\'s been... a long time though. A very long time.','',70338),
(300042,'ruRU','Эти? Я их построил. А мои маленькие друзья помогали. У меня с памятью плохо, но я знаю, что когда-то я много всего выстроил. Огромных размеров! Но потом... я оказался тут, да-да. Теперь мои поделки гораздо мельче и невзрачнее. Но меня они все равно развлекают, ха!\r\n\r\nН-но... Если хочешь, я научу строить и тебя!','',70338),
(300516,'ruRU','','С чего начать? Наш дом на грани краха. Обереги разрушились, и три провинции расходятся все дальше друг от друга. Когда-то шпили Шен\'драмара было видно с западной дозорной башни. Теперь уже нет. Опорные столпы ветшают, и если цепи наконец порвутся...',70291),
(300517,'ruRU','','В чем причина? Если коротко, духи ветра просто... исчезли. Вчера они были, а сегодня их нет. Не описать, что Ваятели Ветра испытали в тот миг. Нас как будто накрыла непроницаемая тишина, а потом... безмерная пустота.\r\n\r\nЖалкие фантомы, которые тебе наверняка уже встречались, не более чем тени величия настоящих духов ветра. Эти неразумные существа блуждают без цели и смысла: бледная пародия на верных друзей, с которыми мы тысячи лет жили в гармонии.',70291),
(300518,'ruRU','','Many disagree on this point. I believe that simple communication is the key. The songs of the wind rang so clearly to us when the spirits were still here. Since they left, it\'s grown quiet and our power as windshapers has weakened. \r\n\r\nHowever, there are those of us who can still hear something. A hushed tone. Fragments of a melody. Those that can still hear and see into the elemental planes must grow in strength. I believe that is the key to our salvation.',70291),
(300519,'ruRU','','Культ? Кучка фанатиков и убийц. Они верят, что мы понесли кару за какой-то неведомый грех. На самом же деле их лидеры – обыкновенные жулики из бывшего ордена сомнительных "жрецов" Ал\'акира Владыки Ветра.\r\n\r\nОни увидели возможность сыграть на страхах нашего народа, чтобы пробиться к власти... И долго раздумывать не стали.',70245),
(300520,'ruRU','','За все годы нашей дружбы с духами ветра они ни разу не выражали к Владыке Ветра никакого благоговения. Да, упоминали о существовании Ал\'акира, но избегали произносить его имя – словно бы в страхе перед ним.\r\n\r\nДаже если этот Ал\'акир – всемогущий "Владыка Ветра" или правитель элементалей воздуха, века жизни бок о бок с духами убедили меня, что он как минимум не самая популярная личность среди обитателей Небесной выси. Боюсь, что попытки договориться с Ал\'акиром лишь приблизят наш роковой конец.',70245),
(300521,'ruRU','','Не забывай, что здесь мы никогда не обретем настоящий дом, пусть даже это измерение приютило нас на многие века. Мы не в земном мире, где появились на свет. Мы в царстве Небесной выси, одной из сфер стихий.\r\n\r\nПрибыли сюда по приглашению духов, с которыми сроднились в древние времена. Теперь шен\'дорай лишились их дружбы – а может, и защиты. Неизвестно, как нас воспримут другие обитатели этого измерения.',70245),
(300522,'ruRU','','Alas, I have prattled on long enough. Seek out my apprentice Ayessa Dawnsinger in the port of Valanaar if you find yourself out that way. She still hears the song--if only faintly. I am old and much of my power has left me. Ayessa represents the future of our people and the path we must now walk to survive. It\'s up to her and young skyborne such as yourself to carry the hopes for our people forward.',70245),
(300621,'ruRU','<Бурлящее облако живых молний угрожающе потрескивает, когда вы подходите ближе. Наверное, лучше уйти. И побыстрее.>','<Бурлящее облако живых молний угрожающе потрескивает, когда вы подходите ближе. Наверное, лучше уйти. И побыстрее.>',70338),
(300626,'ruRU','','Здравствуй, |3-6($c). Хочешь заслужить благословение Владыки Ветра?',70338),
(300638,'ruRU','Скоро шен\'дорай узрят истину... А слепцов сметет грядущая буря!','Скоро шен\'дорай узрят истину... А слепцов сметет грядущая буря!',70338),
(300661,'ruRU','Добро пожаловать! Впервые в городе? Как освоишься, приходи ко мне – скажу, где можно будет подзаработать. Я с ног валюсь от подготовки к Фестивалю Ветров. Соглашусь на любую помощь, лишь бы кладовые не пустели.','',70338),
(300662,'ruRU','Если подумываешь научиться готовить, могу дать парочку советов! Хо-хо! Надевай передник и за дело!','',70338),
(300663,'ruRU','','Здравствуй, дитя. Я Иллайя Янтарный Ветер, старейшина Ваятелей Ветра на острове Зефрис. Мы всегда рады новым гостям из рощи.\r\n\r\nНе бойся, старая шаманка не будет отнимать у тебя время. Тебе наверняка пора отправляться в очередное странствие. Заходи попозже, когда пожелаешь.',70291),
(300665,'ruRU','','Я руковожу делами деревни Шен\'дар, и здесь очень многое нужно держать под контролем. Бандиты, сектанты и прочие неожиданные происшествия – чтобы эта деревня держалась на плаву, приходится немало потрудиться.',70425),
(300678,'ruRU','','<Констебль Аонда о чем-то напряженно размышляет.>',70338),
(300698,'ruRU','Я могу научить тебя делать роскошную кожаную броню, если не будешь лениться.','',70338),
(300702,'ruRU','','Портные-шен\'дорай в своей работе вдохновляются легкостью текущих потоков ветра. Духи нас покинули, и я не знаю, когда снова увижу их танец... Но мое ремесло утешает меня, хоть и отвлекает лишь на время.\r\n\r\nЕсли хочешь, я научу тебя тоже работать с тканью.',70338),
(300714,'ruRU','<Труп покрывают ожоги и красные пятна. Он что-то сжимает в руках.>','<Труп покрывают ожоги и красные пятна. Он что-то сжимает в руках.>',70338),
(301009,'ruRU','Здравствуй, |3-6($c). Добро пожаловать в залы торговой гильдии. Запасы на Зефрисе сейчас оскудели, но здесь ты найдешь столько материалов и товаров, что без труда продолжишь свои приключения.\r\n\r\nЕсли будут вопросы, не стесняйся и задавай.','Здравствуй, |3-6($c). Добро пожаловать в залы торговой гильдии. Запасы на Зефрисе сейчас оскудели, но здесь ты найдешь столько материалов и товаров, что без труда продолжишь свои приключения.\r\n\r\nЕсли будут вопросы, не стесняйся и задавай.',70338),
(301019,'ruRU','Подойди, дитя. Сядь рядом.','',70338),
(301020,'ruRU','Столпы удерживают наш родной остров в мире стихий Небесной выси. Теперь они ветшают, и Зефрис в страшной опасности.','',70338),
(301021,'ruRU','Культ Ал\'акет становится все агрессивнее. А Ваятели ветра упрямо отказываются признавать, что всему виной их бездействие.','',70338),
(301024,'ruRU','Мы совершили фатальную ошибку, когда доверили свою судьбу переменчивым духам стихий. Теперь нам предстоит ее исправить.','',70338),
(301025,'ruRU','','Как ты наверняка помнишь, духи подарили нам столпы ветра, которые связывают нас с миром стихий Небесной выси. Сейчас эти столпы ветшают, и нашему дому грозит катастрофа.',70245),
(301026,'ruRU','','Как будешь проходить мимо порта Валанаара, найди Айессу Певицу Рассвета. Она расскажет подробнее.',70245),
(301027,'ruRU','','Культ Ал\'акет заходит все дальше в своей агрессии. А бездумное применение магии, которое так любит Высший орден, может приблизить нас к гибели.',70245),
(301028,'ruRU','','The Windshapers possess the gift of skysight, and we are working tirelessly to find our lost elemental benefactors, so that they may guide us once again.',70245),
(301029,'ruRU','','Магия шаманов сильно ослабла после исчезновения духов, но мы твердо намерены вернуть их домой.',70245),
(301030,'ruRU','','Мы не отступим, пока не выясним причину. Мы найдем в себе силу призвать духов обратно.',70245),
(301031,'ruRU','','Будущее нашего народа скрывается в тумане, но надежда еще живет, и у нас есть план...',70245),
(301032,'ruRU','С чего начать? Наш дом на грани краха. Обереги разрушились, и три провинции расходятся все дальше друг от друга. Когда-то шпили Шен\'драмара было видно с западной дозорной башни. Теперь уже нет. Столпы ветра, которые удерживают нас в этих сферах, ветшают с каждым днем...','',70338),
(301033,'ruRU','В чем причина? Если коротко, духи ветра просто... исчезли.\r\n\r\nЖалкие фантомы и мелкие элементали, которые тебе наверняка уже встречались, не более чем тусклые подобия настоящих духов ветра. Эти неразумные существа блуждают без цели и смысла: бледная пародия на верных друзей, с которыми мы тысячи лет жили в гармонии.','',70338),
(301034,'ruRU','По этому поводу идут споры. Послушать Ваятелей Ветра – можно просто взяться за руки и надеяться на возвращение духов. Но власть их общины иссякает, а образ жизни зависит от того же цикла взаимозависимости, который и привел нас к краху. Высший же орден... предпочитает более прямой подход.','',70338),
(301035,'ruRU','Культ? Кучка фанатиков и убийц. Они верят, что мы понесли кару за какой-то неведомый грех. На самом же деле их лидеры – обыкновенные жулики из бывшего ордена сомнительных "жрецов" Ал\'акира Владыки Ветра.\r\n\r\nОни увидели возможность сыграть на страхах нашего народа, чтобы пробиться к власти... И долго раздумывать не стали.','',70338),
(301036,'ruRU','Даже Ваятели Ветра тебе скажут, что духи ветра никогда не выказывают своим правителям особого почета. Они упоминали о существовании Ал\'акира, но избегали произносить его имя – словно бы в страхе перед ним.\r\n\r\nДаже если этот Ал\'акир – всемогущий "Владыка Ветра" или правитель элементалей воздуха, зависимость от элементалей как раз и вышла нам боком. Пора исправлять ситуацию своими силами.','',70338),
(301037,'ruRU','You must remember that while this realm has been our home for millennia, we will always be somewhat alien to this place. We are not in the terrestrial world that birthed our people. We are in the realm of Skywall, the elemental plane of air.\r\n\r\nWe arrived here as the guests of spirits with whom we found kinship in ages past. Now that we shen\'dorei find ourselves bereft of their presence--and potentially--their protection, there\'s no telling how the other denizens of this plane may perceive us.','',70338),
(301038,'ruRU','Но хватит мне молоть языком. Найди Элаадрина Вечерняя Буря в порту Валанаара, если будешь проходить мимо. Элаадрин – мой бывший ученик. Теперь он занимает пост главного магистра Высшего ордена. У него сильная воля и большой талант в магии. Наш народ возлагает надежды на него и юных небеснорожденных вроде тебя.','',70338),
(301040,'ruRU','','Если ищешь работу, многие из местных тоже ищут помощника для всевозможных поручений. Просто походи и поспрашивай – обязательно что-нибудь найдешь.',70338),
(301044,'ruRU','Hello there, young $c. I am Rathiril Sunlance and I am an elder Magister of the High Order here on Zephras Isle. It\'s always good to see bright-eyed young shen\'dorei, ready to do their duty in service to their homeland.\r\n\r\nDon\'t let this dusty old mage hold you up, however. No doubt you\'ve got many adventures to see to. Feel free to stop by later if you\'d like to speak more.','',70338),
(301355,'ruRU','Мы с женой держим буреяблочный сад в низинах к западу от Валанаара.','',70338),
(301356,'ruRU','Несколько лет назад на нашу ферму напали бандиты. Они вынесли все подчистую и избили меня до полусмерти. На следующий год, в тот же сезон, они вернулись.','',70338),
(301357,'ruRU','Они опять забрали большую часть урожая, но главарь бандитов... Ферау Верзила, как он себя называет... сказал, что они будут возвращаться каждый сезон и брать вдвое против предыдущего года.','',70338),
(301358,'ruRU','Мы обращались к миротворцам с просьбой отвадить бандитов, но из-за культа у них совершенно не осталось свободных солдат.','',70338),
(301359,'ruRU','В этом году буреяблоки уродились плохо, и нам почти нечем им заплатить. В лучшем случае они просто убьют нас быстро. Но вероятнее, что отберут все и обрекут на голодную смерть.','',70338),
(301362,'ruRU','Я пришел в город нанять бойцов, чтобы прогнать их. Один согласился, но сразу же ограбил меня на выходе из города и чуть не убил.','',70338),
(301364,'ruRU','Я страдаю от ран и не могу даже встать с постели. Умоляю тебя – найди мой сад, расскажи все Аамелии и помоги ей выжить. Пожалуйста... помоги нам.','',70338),
(301399,'ruRU','','Сад Поля Ветров переживает не лучшие времена...',70338),
(301445,'ruRU','Аамелия, дорогуша! Где Альварион? Испугался Ферау и послал тебя?','',70338),
(301446,'ruRU','','Альварион? Он с миротворцами, зачищает холмы от твоих прихвостней. Они вернутся с минуты на минуту и очень тебе обрадуются.',70338),
(301447,'ruRU','HA! A poor bluff! Ferauu has eyes and ears everywhere. I know that it\'s just you and this scrawny stranger here. You\'ve had your fun putting down a few of my weaker recruits, but The Bludgeon is here now and the party is over. Time to pay up, with interest.','',70338),
(301448,'ruRU','','Что-то я заболталась. Спасибо тебе за все...',70338),
(301449,'ruRU','','Аамелия поднимает вилы в угрожающей позе.',70338),
(301450,'ruRU','','Хм... Неожиданный поворот. Ну зато мы теперь знаем, зачем нужна эта штуковина. Давай вернемся в дом.',70338),
(301451,'ruRU','','Здравствуй! Я Сания Серебряный Поток – миссионер и верная слуга нашего всемогущего господина Ал\'акира Владыки Ветра.\r\n\r\nАл\'акетов презрительно называют жестокой "сектой", но на самом деле мы стремимся к миру и просветлению. Наш господин Ал\'акир – величайший правитель Небесной выси, и лишь его милостью мы спасемся от бед, постигших наш народ.\r\n\r\nЕсли тебе интереснее хорошие новости, приходи ко мне когда захочешь. Да благословит тебя Владыка Ветра.',70338),
(301455,'ruRU','<Лежащий мужчина неловко дергается. Он выздоравливает после очень неприятных ран.>','',70338),
(301456,'ruRU','Всегда рад видеть тебя, $n.','',70338),
(301472,'ruRU','Если ты от Ратирила, то уже понимаешь, какой кризис мы сейчас переживаем.','',70338),
(301473,'ruRU','Высший орден ищет прагматичное и цивилизованное решение нашего кризиса.','',70338),
(301474,'ruRU','Которое не уповает на чудесное спасение от сторонних сил. Надо самим ковать свою судьбу – впервые с переселения в Небесную высь.','',70338),
(301475,'ruRU','Since we left our homes in Kalimdor, the world has grown. They call it "Azeroth" now and it\'s a massive, vibrant world.','',70338),
(301476,'ruRU','Недавно мы сумели прорезать своего рода "замочную скважину", которая позволила нам заглянуть между измерениями и многое узнать об Азероте.','',70338),
(301478,'ruRU','Когда мы заглянули в эту замочную скважину, кто-то смотрел с той стороны. Маги из похожего ордена, который называется Кирин-Тор. Мы очень многое от них узнали.','',70338),
(301480,'ruRU','Элементали, которые привели нас сюда, исчезли. Любые их чары, оберегавшие наш дом, можно заменить магией высокорожденных. Но в Небесной выси наша сила угасла.','',70338),
(301481,'ruRU','Кому-то из нас нужно оставить это измерение и отправиться на Азерот. Там мы вновь обретем утраченные знания и вернемся сюда, чтобы спасти наш дом.','',70338),
(301482,'ruRU','Кирин-Тор любезно согласился принять нас как гостей, и их помощь будет незаменима для наших целей.','',70338),
(301483,'ruRU','Нам понадобятся исследователи и первооткрыватели всех мастей. Подумай над моим предложением. Надеюсь, ты присоединишься к нам, когда придет время. А пока – удачи.','',70338),
(301839,'ruRU','<Небеснорожденный лежит без сознания.>','<Небеснорожденный лежит без сознания.>',70338),
(301843,'ruRU','Мм-м... что... что происходит? Что это?..','',70338),
(301844,'ruRU','My... head... ohh it hurts! What... who are you? Why... are you carrying me?','',70338),
(301845,'ruRU','Пожалуйста... Положи меня... На те одеяла у дерева...','',70338),
(301874,'ruRU','It is encouraging to know that Elaadrin and his mages are finally with us. With both the High Order and the Windshapers working with us against the greater threat, we stand a much better chance to thwart the Al\'Aketh and whatever they have planned for Valanaar.','',70338),
(301876,'ruRU','Что касается тебя, |3-6($c). Я слышал про стычку с Ваятелями Ветра у каменных монолитов...','',70338),
(301877,'ruRU','Возмездие еще свершится. А пока надеюсь, что Ваятели Ветра с Высшим орденом согласятся объединиться против культа. Сейчас Ал\'акет – главная угроза Зефрису.','',70338),
(301916,'ruRU','<Сектант мертв. Осмотрев его внимательно, вы замечаете, что он оберегающим жестом прижимает что-то к груди.>','<Сектант мертв. Осмотрев его внимательно, вы замечаете, что он оберегающим жестом прижимает что-то к груди.>',70338),
(302043,'ruRU','Приветствую.','Здравствуйте.',70338),
(302044,'ruRU','Что вы ищете?','Что вы ищете?',70338),
(302046,'ruRU','Вам помочь что-то найти?','Вам помочь что-то найти?',70338),
(302047,'ruRU','Могу я помочь вам в поисках?','Могу я помочь вам в поисках?',70425),
(302063,'ruRU','','Большая часть острова подвергается безнаказанным бесчинствам сектантов, поэтому Лортуна думает, что мы теряем контроль над ситуацией. Можно сыграть на ее самоуверенности.',70338),
(302064,'ruRU','','Если провести отвлекающий маневр у святилища, небольшой отряд миротворцев, Ваятелей Ветра и Высшего ордена сумеет пробить фланг и прорваться к внутреннему алтарю. А там мы ликвидируем саму верховную жрицу и отрубим змее голову.',70338),
(302065,'ruRU','','Поговори сначала с лидером Ваятелей Ветра, а потом – Высшего ордена. Они недолюбливают друг друга, но у них хватит ума понять, что сейчас важнее борьба с Ал\'акетом. Уговори их поддержать план и возвращайся ко мне.',70338),
(302070,'ruRU','','Айесса Певица Рассвета смеривает вас взглядом, едва сдерживая гнев.> \r\n\r\nНа твоих руках кровь Ваятелей Ветра. Заявиться сюда после такого может или исключительный храбрец, или исключительный глупец. Мы нескоро прощаем и ничего не забываем.\r\n\r\nНа твоем месте я бы убралась отсюда. Твое счастье, что я не хочу тебя убивать на виду у всего Зефриса.',70338),
(302073,'ruRU','','Хм... Ясно. Ну хорошо, |3-6($c). Ваятели Ветра поддержат план. Передай Валеннии, что в этот раз она может на нас рассчитывать.\r\n\r\n<Айесса угрожающе понижает голос.> \r\n\r\nНе путай поддержку с прощением. На тебе кровавый долг, и однажды мы придем за расплатой.',70338),
(302079,'ruRU','Здравствуй. Я Элаадрин Вечерняя Буря, верховный магистр Высшего ордена. Чем могу помочь?','',70338),
(302085,'ruRU','The Windshapers are almost wholly to blame for everything that has happened. Their refusal to change has damaged our ability to save ourselves from our current peril. They speak in absolutes and treat assumptions and superstitious hope as fact.\r\n\r\nDo you know who else deals only in absolutes? The Al\'Aketh. \r\n\r\nI for one do not intend to let blind adherence to dangerous beliefs doom our people. If it weren\'t for the threat of the cult, I\'d march our mages over to the other side of Valanaar and wipe the Windshapers out.','',70338),
(302087,'ruRU','Ясно. Мы идем на огромный риск, но в нашем положении выбирать не приходится.\r\n\r\nХорошо, Ваятели Ветра поддержат план. Передай Валеннии, что в этот раз она может на нас рассчитывать.','',70338),
(302093,'ruRU','Миротворцы сами понимают, что у них недостает сил для открытого нападения на святилище. Без подкреплений от Ваятелей Ветра и Высшего ордена у нас нет шансов. Обе фракции поклялись протянуть руку помощи в ответ на наш призыв. Удар надо нанести сейчас.\r\n\r\nК сожалению, недавно конфликт между ними перерос в кровопролитие, и примирить их будет тяжело.\r\n\r\nКак насчет небольшой дипломатической миссии?','Миротворцы сами понимают, что у них недостает сил для открытого нападения на святилище. Без подкреплений от Ваятелей Ветра и Высшего ордена у нас нет шансов. Обе фракции поклялись протянуть руку помощи в ответ на наш призыв. Удар надо нанести сейчас.\r\n\r\nК сожалению, недавно конфликт между ними перерос в кровопролитие, и примирить их будет тяжело.\r\n\r\nКак насчет небольшой дипломатической миссии?',70338),
(302159,'ruRU','','<Валенния тяжело ранена. Ей стоит большого труда не упасть в обморок.>',70338),
(302160,'ruRU','','Most of the cultists at the Sanctum of Storms seem to have come out to respond to our attack. I never would have expected this to go so well. This was almost too easy...\r\n\r\nI think that the Windshapers and High Order have made their push. Valennia should be with them. You should head inside and find her. We\'ll stay here and keep watch while Valennia and the others finish what they came here to do.',70338),
(302282,'ruRU','You\'ll need to speak with Skypriest Aanders for instruction. There is no guidance I can provide. Be gone with you, recruit.','You\'ll need to speak with Skypriest Aanders for instruction. There is no guidance I can provide. Be gone with you, recruit.',70338),
(302443,'ruRU','Мы пришли, как только нам сообщили новости. Высший орден готов служить Зефрису.','',70338),
(302444,'ruRU','','...И Ваятели Ветра. Мы поддержим нападение на святилище, Валенния.',70338),
(302445,'ruRU','','Благодарю. По правде говоря, мы ведем опасную игру и не обязательно выиграем. Надо понимать, что тебе может выпасть билет в один конец.',70338),
(302446,'ruRU','','Мы-то понимаем. К слову, я встретилась с Элаадрином и мы распорядились послать за... помощью со стороны. Неизвестно, придет она вовремя или нет. А может, не придет вовсе...',70338),
(302447,'ruRU','','Со... стороны? Из других провинций? Мы потеряли связь с остальными островами много лет назад!',70338),
(302448,'ruRU','Не с островов, а... чуть подальше. Объясним по дороге.','',70338),
(302449,'ruRU','','Ну хорошо. Время не терпит, поэтому начнем подготовку. Спасибо всем за помощь. Зефрис перед вами в долгу.',70338),
(302631,'ruRU','','Aonda is a good woman, and a true servant of Zephras Isle. It is my hope that you can quickly earn her trust and help her to keep Shen\'dar Village safe. May the winds guide you, $n.',70338),
(302649,'ruRU','','Ал\'акир благословляет тебя. Но берегись: если решишь обмануть последователей Владыки Ветра, навлечешь на себя его гнев.',70338),
(302650,'ruRU','<Двое сектантов разговаривают недалеко от вас. Можно спрятаться за шкафом и подслушать – вдруг проскочит что-то интересное.>','<Двое сектантов разговаривают недалеко от вас. Можно спрятаться за шкафом и подслушать – вдруг проскочит что-то интересное.>',70338),
(302703,'ruRU','<The skyborne before you sways unsteadily, clearly very inebriated.>\r\n\r\nI used to be a sailor, you know? Before the trouble started. The skycutters used to run between the islands. Now it\'s unsafe or some such, or so they say.\r\n\r\nI see the High Order and the Windshapers have their skycutters running again, but I\'m stuck here, grounded!\r\n\r\nWhat aren\'t we being told!\r\n\r\n<He turns and yells loudly at the innkeeper.>\r\n\r\nWHAT AREN\'T WE BEING TOLD, DONAAL!?','',70338),
(302705,'ruRU','Я говорю, народ, проклятый это лес! Я СВОИМИ ГЛАЗАМИ *ик* ВИДЕЛ!','',70338),
(302706,'ruRU','Если мне не веришь, иди и посмотри! Дикие ветряные умертвия *ик*... Лесные духи грызут за лодыжки!','',70338),
(302707,'ruRU','Там даже есть злобный лесной призрак! Весь в черном и... жуткий такой! Проклятый лес, про-кля-тый! *ик*','',70338),
(302807,'ruRU','Если у тебя есть дар к друидскому искусству, я могу научить.','Если у тебя есть дар к друидскому искусству, я могу научить.',70338),
(302809,'ruRU','The followers of the old Highborne ways have never been more hungry to gain knowledge and reclaim what we\'ve lost. If you would seek to wield the power of the arcane and have the aptitude, I can help you take your next steps.','The followers of the old Highborne ways have never been more hungry to gain knowledge and reclaim what we\'ve lost. If you would seek to wield the power of the arcane and have the aptitude, I can help you take your next steps.',70338),
(302811,'ruRU','Зефрис срочно нуждается в охотниках и следопытах. Ветра бушуют все суровее, а магия уже не так надежно скрепляет наш остров. Дикие леса одичали еще сильнее, и только мы с соратниками можем защитить наш народ.\r\n\r\nЕсли у тебя есть дар к ремеслу охотника, я могу вооружить тебя знаниями о выживании в чаще.','Зефрис срочно нуждается в охотниках и следопытах. Ветра бушуют все суровее, а магия уже не так надежно скрепляет наш остров. Дикие леса одичали еще сильнее, и только мы с соратниками можем защитить наш народ.\r\n\r\nЕсли у тебя есть дар к ремеслу охотника, я могу вооружить тебя знаниями о выживании в чаще.',70291),
(302814,'ruRU','Рази врагов и обольщай сердца одним простым трюком.\r\n\r\nЕсли пойдешь по пути разбойника, я могу тебя обучить... за кое-какую плату, конечно.','Рази врагов и обольщай сердца одним простым трюком.\r\n\r\nЕсли пойдешь по пути разбойника, я могу тебя обучить... за кое-какую плату, конечно.',70338),
(302815,'ruRU','Хотя духи ветра нас покинули, сила стихий потеряла с нами связь не полностью... Если хватит терпения ее добиться.\r\n\r\nЯ помогаю посвященным в тайны шаманизма постигнуть их глубже.','Хотя духи ветра нас покинули, сила стихий потеряла с нами связь не полностью... Если хватит терпения ее добиться.\r\n\r\nЯ помогаю посвященным в тайны шаманизма постигнуть их глубже.',70338),
(302817,'ruRU','Миг сомнения стоит воину жизни. Если ты не боишься смотреть смерти в лицо, я отучу тебя сомневаться.','Миг сомнения стоит воину жизни. Если ты не боишься смотреть смерти в лицо, я отучу тебя сомневаться.',70338),
(302824,'ruRU','You might think that just because we live on a floating island, there would be no need for miners like me. After so many thousands of years, however, we still manage to dig up a lot of interesting things.\r\n\r\nIt\'s almost like there\'s some invisible force, constantly creating new mineral deposits every so often. That\'s magic for you though, right?\r\n\r\nRegardless, if you need training as a miner, then I\'m your shen\'dorei.','You might think that just because we live on a floating island, there would be no need for miners like me. After so many thousands of years, however, we still manage to dig up a lot of interesting things.\r\n\r\nIt\'s almost like there\'s some invisible force, constantly creating new mineral deposits every so often. That\'s magic for you though, right?\r\n\r\nRegardless, if you need training as a miner, then I\'m your shen\'dorei.',70338),
(303598,'ruRU','','Oh, and a word of warning before you head up to Shadowgale Forest. It\'s incredibly dangerous up there. Some even say it\'s haunted. Make sure you are prepared and well-equipped if you plan to make the trek.',70338),
(303612,'ruRU','Добро пожаловать в таверну "Спокойный бриз". Желаешь перекусить или освежиться?','Добро пожаловать в таверну "Спокойный бриз". Желаешь перекусить или освежиться?',70338),
(304010,'ruRU','Что тебе нужно, дитя Зефриса?','',70338),
(304012,'ruRU','','Чем один Ваятель Ветра может послужить другому?',70245),
(304013,'ruRU','','Я вижу по твоей ауре, что в тебе кровь высокорожденных. У представителей Высшего ордена мало общего с нашей фракцией Ваятелей Ветра. Если не считать относительного мира Тендалской рощи, раскол между нами пролегает очень глубоко. Так глубоко, что доходит до вражды и даже кровопролития.\r\n\r\nВ странствиях по Зефрису никогда не забывай, на чьей ты стороне. И еще хочу предупредить... не зли Ваятелей Ветра.',70338),
(304014,'ruRU','Приветствую новопосвященного от имени Высшего ордена.','',70338),
(304299,'ruRU','','Лортуна! Прекрати это безумие. Ты понятия не имеешь, что случится после разрушения оберегов. Ты можешь обречь нас всех на гибель!',70338),
(304303,'ruRU','','Айесса... моя бывшая сестра. Как же низко ты пала, если якшаешься с гадинами из Высшего ордена.',70338),
(304304,'ruRU','Я с тобой церемониться не буду, ведьма. Заканчивай свои игры, и я убью тебя быстро. Не торгуйся – ничего лучше ты от Высшего ордена не добьешься.','',70338),
(304307,'ruRU','','После разрушения оберегов? Глупцы! Обереги уже несколько дней как разрушены. Нет, я просто зажигаю маяк... для истинных служителей Ал\'акира.',70338),
(304433,'ruRU','','Наконец-то! Наш призыв услышан. Покоритесь погибели с радостью!',70338),
(304441,'ruRU','Кто смеет призывать повелителя восточного ветра?','',70338),
(304443,'ruRU','Так слухи оказались правдой. Мои своенравные братья хорошо спрятали это место от взора Ал\'акира.','',70338),
(304445,'ruRU','','Да! Да! Врата к Зефрису – моя заслуга! Представь меня своему Владыке Ветра, чтобы он признал вестницу его величия!',70338),
(304447,'ruRU','Решила мне приказывать, смертная? Ошибаешься. Прочь с дороги, жалкая эльфийка!','',70338),
(304448,'ruRU','','Нет! Никогда! Я бы никогда не посмела!',70338),
(304449,'ruRU','Это точно, червь. Больше не посмеешь. Ха!','',70338),
(304452,'ruRU','Живите свои жалкие жизни во владениях моего повелителя до его неизбежного приговора. Рано или поздно его суд вас настигнет.','',70338),
(304454,'ruRU','Теперь, когда это чудесное царство больше от нас не скрыто, вы познакомитесь с НАСТОЯЩИМИ детьми Небесной выси...','',70338),
(304558,'ruRU','Кончай трепаться, Полоскун. Последних клиентов распугаешь своими пьяными байками про привидений!','Кончай трепаться, Полоскун. Последних клиентов распугаешь своими пьяными байками про привидений!',70338),
(304626,'ruRU','','Столько всего, что мне уже страшно. Шайка бандитов поселилась в пещере к северу и устраивает налеты. А на юге культ Ал\'акет недавно захватил деревню Фалаат. Я доверяю каждому миротворцу и поселянину, но таким малым числом невозможно защитить деревню.\r\n\r\nЕсли культ решит двигаться дальше в нашу сторону, мы едва ли их остановим.',70338),
(305044,'ruRU','Зефрис в великой опасности. Духи ветра привели наш народ в Небесную высь тысячи лет назад, но теперь они покинули нас и оставили без защиты в этом непрочном измерении. Когда-то наше процветающее общество населяло несколько заповедных островов Небесной выси, а сейчас мы даже точно не знаем, что случилось с шен\'дорай на других островах.\r\n\r\nМы переживаем тяжелые времена, но Высший орден не перестанет бороться за наше будущее.','',70338),
(305106,'ruRU','Прости за опоздание, Айесса.','',70338),
(305107,'ruRU','Не сразу я уговорил верховного мага Ронина помочь мне с межпространственным порталом...','',70338),
(305108,'ruRU','Ansirem! This isn\'t how I expected our first meeting to go, but I\'m glad you made it!','',70338),
(305109,'ruRU','','Я тоже по-другому представляла нашу первую встречу, Мулн.',70338),
(305110,'ruRU','Прямо на слезу прошибает. У длинноухих, оказывается, есть друзья из... откуда-то снизу.','',70338),
(305111,'ruRU','Мы не ссорились с тобой, повелитель восточного ветра. Не тревожь нас.','',70338),
(305112,'ruRU','Хорошо, смертные. Пока что я сжалюсь над вами. Мне не терпится рассказать обо всем Владыке Ветра. Мы с вами еще встретимся... очень скоро.','',70338),
(305131,'ruRU','','Пустые угрозы, Элаадрин. Даже если вы схватите меня, мой великий труд подошел к концу. Вам повезло: вы очутились в оке бури в нужный момент и увидите плоды наших стараний своими глазами.',70338),
(305132,'ruRU','Подождите... Где мы? Откуда все это во владениях Владыки Ветра?','',70338),
(305133,'ruRU','Нам пора уходить. Я открою портал в Валанаар.','',70338),
(305134,'ruRU','','Мулн Гнев Земли из Служителей Земли – Ваятели Ветра примут тебя как дорогого гостя.',70338),
(305135,'ruRU','Приветствуем и тебя, верховный маг Руномант. Высший орден очень интересуется Кирин-Тором.','',70338),
(305160,'ruRU','Искатель приключений! Мост ветра к другому шпилю держится непрочно. Подожди со мной, пока он не появится снова.','Искательница приключений! Мост ветра к другому шпилю держится непрочно. Подожди со мной, пока он не появится снова.',70338),
(305849,'ruRU','Верховная жрица, мы готовы исполнить твою волю. Я поведу наступление на западную дозорную башню, а полковник Циклий возглавит атаку на деревню Шен\'дар. Мы займем оба пункта к завтрашнему утру.','Верховная жрица, мы готовы исполнить твою волю. Я поведу наступление на западную дозорную башню, а полковник Циклий возглавит атаку на деревню Шен\'дар. Мы займем оба пункта к завтрашнему утру.',70338),
(305850,'ruRU','','Небесный жрец Аандерс, мы близимся к нашей цели. От твоего успеха зависит многое.',70338),
(305851,'ruRU','Конечно, верховная жрица. Мы твои послушные орудия. Я желаю лишь одного – чтобы ты узрела наш триумф лично.','Конечно, верховная жрица. Мы твои послушные орудия. Я желаю лишь одного – чтобы ты узрела наш триумф лично.',70338),
(305852,'ruRU','','У меня сейчас другие дела, а ваша роль – лишь одна из фигур на доске. Не подведи меня, Аандерс.',70338),
(305853,'ruRU','Да, верховная жрица!','Да, верховная жрица!',70338),
(305854,'ruRU','Ты просишь благословение у Владыки Ветра?','Ты просишь благословение у Владыки Ветра?',70338),
(306235,'ruRU','Я не держу обиды на отдельных членов Ваятелей Ветра вроде тебя, но и развлекать разговорами не собираюсь. Ступай по своим делам, однако запомни: пока ты на острове, лучше обходи стороной Высший орден и наших агентов.\r\n\r\nВысший орден не провоцирует конфликтов... Но он их радикально заканчивает, если нас куда-то все же втягивают. Не путайся у нас под ногами, Ваятель Ветра.','',70291),
(306273,'ruRU','I hope that your interruption is for a good cause. I was in the middle of some important work.','I hope that your interruption is for a good cause. I was in the middle of some important work.',70338),
(306274,'ruRU','Ветра приветствуют тебя, друг. Чем я могу помочь?','Ветра приветствуют тебя, друг. Чем я могу помочь?',70338),
(306276,'ruRU','А, привет. Вижу, ты хочешь задать мне вопрос.','А, привет. Вижу, ты хочешь задать мне вопрос.',70338),
(306278,'ruRU','Да благословят тебя ветра судьбы. Чем могу помочь?','Да благословят тебя ветра судьбы. Чем могу помочь?',70338),
(306574,'ruRU','$n, подготовь союзников к будущей битве с Лортуной и поговори со мной, когда решишь начать.','',70338),
(306593,'ruRU','<Следопыт не отрывает взгляд от огромного опорного столпа вдалеке.>','<Следопыт не отрывает взгляд от огромного опорного столпа вдалеке.>',70338),
(307118,'ruRU','<Before you lies the corpse of Jorel Windsinger.\r\n\r\nDeep lacerations are cut into his legs, and lightning burns scorch his fur.\r\n\r\nIt is clear he put up a fight before succumbing to his wounds.>','<Before you lies the corpse of Jorel Windsinger.\r\n\r\nDeep lacerations are cut into his legs, and lightning burns scorch his fur.\r\n\r\nIt is clear he put up a fight before succumbing to his wounds.>',70338),
(307316,'ruRU','The spirit of strength does not always refer to physical strength. To face adversity both from within and without is what it means to take my shape.','',70338),
(307912,'ruRU','Следи за языком, |3-6($c). Ваятели Ветра не потерпят оскорблений от Высшего ордена.','Следи за языком, |3-6($c). Ваятели Ветра не потерпят оскорблений от Высшего ордена.',70338),
(307942,'ruRU','Добро пожаловать в Валанаар, |3-6($c).','',70338),
(307944,'ruRU','Не забывай наведываться к Высшему ордену – вдруг мы найдем тебе какое-нибудь поручение. А пока удачи в путешествиях!','',70338),
(309474,'ruRU','<Before you lies a skyborne; his body is mangled and bruised but still recognizable. It is clear he met a gruesome end while attempting to flee.\r\n\r\nIt appears that all of his belongings are still on his body, and a half-filled crate nearby lies spilled on the ground.>','',70338),
(309828,'ruRU','Да пребудет с тобой ветер, друг. Мне поручили открыть небеснорожденным путь напрямую в Штормград. Можешь пользоваться порталом в любое время.','',70425),
(312713,'ruRU','Скучно мне тут наверху. Всех развлечений – побесить противного зануду Халаана, да и то быстро надоедает.','Скучно мне тут наверху. Всех развлечений – побесить противного зануду Халаана, да и то быстро надоедает.',70338),
(312724,'ruRU','Эй! Осторожней там! Священные дары шен\'дорай – это тебе не игрушка!','',70338),
(312725,'ruRU','Эх... Молодежь!','',70338),
(312929,'ruRU','Не хочу тебя расстраивать, |3-6($c), но у тебя пока мало опыта для островов Черного Копья.','Не хочу тебя расстраивать, |3-6($c), но у тебя пока мало опыта для островов Черного Копья.',70338),
(313248,'ruRU','Присаживайся к огню, и мы начнем.','',70338),
(313249,'ruRU','Чтобы разбить лагерь, надо всего лишь развести костер. Учителя кулинарии покажут тебе, как.','',70338),
(313250,'ruRU','После костра переходи к другим объектам и расставляй их вокруг.','',70338),
(313251,'ruRU','Умелые кожевники, например, могут натянуть палатку – вроде той, что позади меня.','',70338),
(313253,'ruRU','В любой профессии есть свои преимущества для лагеря, даже у рыбной ловли!','',70338),
(313254,'ruRU','А потом остается только сесть и погреться у костра. Через несколько минут отдыха ты получишь ауры, которые помогут в путешествиях.','',70338),
(313255,'ruRU','Если задержишься еще на пару секунд, моя палатка тоже передаст тебе полезную ауру.','',70338),
(313256,'ruRU','Вот, собственно, и все. Как только получить ауру от костра, поговори со мной еще раз.','',70338),
(313452,'ruRU','Вы уже видели? Неборезы снова вышли из гаваней! Правда, движения между шен\'дорайскими островами все равно пока нет.\r\n\r\nНадеюсь, мы скоро восстановим маршруты к Шен\'драмару и Элдранаару... Если от них что-то осталось.','Вы уже видели? Неборезы снова вышли из гаваней! Правда, движения между шен\'дорайскими островами все равно пока нет.\r\n\r\nНадеюсь, мы скоро восстановим маршруты к Шен\'драмару и Элдранаару... Если от них что-то осталось.',70338),
(313453,'ruRU','Ваятели Ветра и Высший орден что-то затевают. Ходят слухи, что обе фракции планируют снова запустить неборезы и сбежать на них из Небесной выси. Сбежать из Небесной выси! Просто смешно. И куда они тогда пойдут?','Ваятели Ветра и Высший орден что-то затевают. Ходят слухи, что обе фракции планируют снова запустить неборезы и сбежать на них из Небесной выси. Сбежать из Небесной выси! Просто смешно. И куда они тогда пойдут?',70291),
(313454,'ruRU','Если мы срочно не остановим культ Ал\'акет, нас всех загребут в фанатики. А мне категорически не идет бритая голова.','Если мы срочно не остановим культ Ал\'акет, нас всех загребут в фанатики. А мне категорически не идет бритая голова.',70338),
(313455,'ruRU','Ты знаешь, что случилось с Бан\'эталом? Миротворцы запрещают подходить к руинам и вообще к Теневейному лесу.\r\n\r\nКто-то в таверне болтал про злобных духов ветра. Якобы они являются в виде туманного силуэта, как будто... из них вынули сердцевину.\r\n\r\nМурашки по коже от таких мыслей.','Ты знаешь, что случилось с Бан\'эталом? Миротворцы запрещают подходить к руинам и вообще к Теневейному лесу.\r\n\r\nКто-то в таверне болтал про злобных духов ветра. Якобы они являются в виде туманного силуэта, как будто... из них вынули сердцевину.\r\n\r\nМурашки по коже от таких мыслей.',70338),
(313456,'ruRU','Неборезы все чаще проходят по небесам. Хорошо, что их сумели запустить снова. Если бы еще старейшины рассказали нам, что происходит... Они продолжают твердить, что ничего не изменилось и связи с другими островами нет.\r\n\r\nЯ постоянно ломаю голову над всеми этими загадками...','Неборезы все чаще проходят по небесам. Хорошо, что их сумели запустить снова. Если бы еще старейшины рассказали нам, что происходит... Они продолжают твердить, что ничего не изменилось и связи с другими островами нет.\r\n\r\nЯ постоянно ломаю голову над всеми этими загадками...',70338),
(313457,'ruRU','Культ Ал\'акет перерастает в серьезную проблему, и миротворцы не в состоянии его остановить. Можно только надеяться, что Ваятели Ветра и Высший орден отложат свои пререкания, чтобы вместе с миротворцами озаботиться нашей защитой.\r\n\r\nМне вообще не хочется вступать ни в какие культы!','Культ Ал\'акет перерастает в серьезную проблему, и миротворцы не в состоянии его остановить. Можно только надеяться, что Ваятели Ветра и Высший орден отложат свои пререкания, чтобы вместе с миротворцами озаботиться нашей защитой.\r\n\r\nМне вообще не хочется вступать ни в какие культы!',70338),
(313458,'ruRU','Культ Ал\'акет утверждает, что "Владыка Ветра" Ал\'акир спасет нас от бед на Зефрисе. Если Ал\'акира не выдумали и он в самом деле правит Небесной высью, почему духи ветра так долго отказывались о нем говорить?\r\n\r\nИли его не существует, или хуже – он существует и сектанты сильно приукрасили его доброту. В любом случае, для простых эльфов вроде нас ничем хорошим не кончится.','Культ Ал\'акет утверждает, что "Владыка Ветра" Ал\'акир спасет нас от бед на Зефрисе. Если Ал\'акира не выдумали и он в самом деле правит Небесной высью, почему духи ветра так долго отказывались о нем говорить?\r\n\r\nИли его не существует, или хуже – он существует и сектанты сильно приукрасили его доброту. В любом случае, для простых эльфов вроде нас ничем хорошим не кончится.',70338),
(313459,'ruRU','Be wary of anyone you meet with grey robes and a shaved head. They call themselves the Al\'Aketh, and they are a menace. \r\n\r\nI even heard that they\'ve been doing things to the anchor pylons around the island.\r\n\r\nIf the Windshapers are to be believed, those pylons are the only thing keeping Zephras afloat here in the elemental plane. It would be madness to tamper with them!','Be wary of anyone you meet with grey robes and a shaved head. They call themselves the Al\'Aketh, and they are a menace. \r\n\r\nI even heard that they\'ve been doing things to the anchor pylons around the island.\r\n\r\nIf the Windshapers are to be believed, those pylons are the only thing keeping Zephras afloat here in the elemental plane. It would be madness to tamper with them!',70245),
(313486,'ruRU','Приветствую тебя, путник.','Приветствую тебя, путница.',70338),
(313648,'ruRU','Ночекогти не придут в восторг от дерзких лазутчиков. Соблюдай осторожность в Теневейном лесу, |3-6($c).','',70338),
(314601,'ruRU','Подожди, да... этот кристалл! Валенния, это...','',70338),
(314602,'ruRU','','...кристалл возвращения для записи важных событий.',70338),
(314603,'ruRU','Перебежчик надеялся предложить его нам в обмен на защиту.','',70338);
INSERT IGNORE INTO `broadcast_text_locale` (`ID`,`locale`,`Text_lang`,`Text1_lang`,`VerifiedBuild`) VALUES
(314604,'ruRU','','Но кристалл сильно поврежден. Запись, скорее всего, тоже пострадала, поэтому надо тщательнее прислушиваться.',70338),
(314605,'ruRU','Активируй его, Валенния. Нужно узнать как можно больше из этих данных.','',70338),
(314606,'ruRU','','...безотлагательно. Немедленно собирайте войска в поход. Столпы – главная опора, а... обереги... исчезнет. Это...',70338),
(314607,'ruRU','','...скорее. Наша армия... уязвимость... мой ритуал нельзя...',70338),
(314608,'ruRU','','Я одна... эта задача... Владыка Ветра... наши голоса... он придет... последний шанс!',70338),
(314609,'ruRU','','Боюсь, из кристалла больше ничего не выжмешь.',70338),
(314610,'ruRU','Обереги... что там было про обереги, Валенния?','',70338),
(314611,'ruRU','','Опорные столпы удерживают нас в воздухе и к тому же выполняют роль оберегов! Шал\'нан об этом упоминал. Они защищают нас от...',70338),
(314612,'ruRU','...всех остальных обитателей Небесной выси. Да спасут нас духи... Так вот в чем ее план. Разрушить обереги и впустить своего "Владыку Ветра"!','',70338),
(316310,'ruRU','Нам необходимо узнать больше о замыслах культа, но эта важнейшая информация могла умереть вместе с перебежчиком...','',70338),
(316364,'ruRU','','Наверное, так и есть. Я и другие мои элитные бойцы раньше состояли в ордене "Поднебесные клинки". Мы служили личной стражей нашего бывшего правителя Шал\'нана.\r\n\r\nВ нынешние неспокойные времена мы в меру своих сил командуем гражданским ополчением миротворцев: мы на Зефрисе единственные более-менее профессиональные солдаты.',70338),
(316366,'ruRU','','<Valennia looks away briefly before looking hesitantly back in your direction.>\r\n\r\nThe Shal\'nan was the very best of us. It was he who stood up for our people against madness and oppression in Eldre\'Thalas nearly ten thousand years ago. It was the Shal\'nan who led us across the uncharted sea to escape the murderous vengeance of our ancient enemies.\r\n\r\nIt was the Shal\'nan who brokered the pact of friendship with the wind spirits that allowed us to ascend to Skywall... and survive.\r\n\r\nHe was ever the servant leader to his people, even after he abdicated his position of power and retired.',70338),
(316368,'ruRU','','Большинство шен\'дорай разве что перемолвилось с ним парой слов. Наверное, из более тесных знакомств только я дожила до сегодняшнего дня.\r\n\r\nЯ служила капитаном "Поднебесных клинков" почти девять сотен лет, пока однажды он не... покинул нас.\r\n\r\nНо даже я не могу сказать, что по-настоящему его знала. Он держался отстраненно и предпочитал одиночество. Проводил большую часть времени в уединении или в разговорах с духами на высоких шпилях над святилищем Четырех Ветров... Сектанты теперь называют его святилищем Акира.',70338),
(316370,'ruRU','','Если бы я знала, жить на Зефрисе было бы намного проще. Эта тайна вызывает среди нас бессчетные беды и раздоры.\r\n\r\nЯ не виню тебя за любопытство, но больше ничего об этом сказать сейчас не могу.',70338),
(316402,'ruRU','Если ты не прочь поучиться, могу показать, как обращаться с кузнечным молотом.','Если ты не прочь поучиться, могу показать, как обращаться с кузнечным молотом.',70291),
(316763,'ruRU','<Зверь тихо щелкает клювом.>','',70338),
(316767,'ruRU','<Буреног издает мягкое воркотание, когда вы подходите ближе.>','',70338),
(316769,'ruRU','<Буреног смотрит на вас с неприкрытым восторгом. Кажется, птица слегка подпрыгивает в нетерпении.>','',70338),
(318281,'ruRU','Welcome to Fairweather Stables! I would love to provide you with one of our fine galestriders, but it seems like you may not yet have enough experience to ride one.\r\n\r\nThey are temperamental at times and are prone to toss newer riders if not handled correctly. I would be more than happy to provide the training for you once you are a more seasoned adventurer and have enough coin!','Welcome to Fairweather Stables! I would love to provide you with one of our fine galestriders, but it seems like you may not yet have enough experience to ride one.\r\n\r\nThey are temperamental at times and are prone to toss newer riders if not handled correctly. I would be more than happy to provide the training for you once you are a more seasoned adventurer and have enough coin!',70338),
(319470,'ruRU','С-слизь! Р-ра-а...','',70338),
(320568,'ruRU','Приветствую.','Приветствую.',70338),
(321113,'ruRU','Да проклянет буря этих фанатиков из Ал\'акета!','Да проклянет буря этих фанатиков из Ал\'акета!',70338),
(321197,'ruRU','Добро пожаловать в банк Валанаара. Твое ценное имущество будет у нас в безопасности. Хочешь проверить свою ячейку?','Добро пожаловать в банк Валанаара. Твое ценное имущество будет у нас в безопасности. Хочешь проверить свою ячейку?',70338),
(321203,'ruRU','Тебе удалось заслужить доверие Когтя Ночи, |3-6($c). Нам нечего предложить тебе в награду, – но есть чертежи, добытые в руинах Бан\'этала.\r\n\r\nМаги-кузнецы Бан\'этала считались лучшими мастерами на Небесных островах. Друиды Когтя Ночи пользуются дарами природы, так что чертежи ремесленников нам ни к чему.\r\n\r\nПродолжай нас поддерживать, и я раскрою тебе их секреты.','',70338),
(321408,'ruRU','Приветствую тебя, |3-6($c). Тебе нужно оружие?\r\n\r\nМоим наставником был Антарион из Бан\'этала, и он обучил меня древним тайнам магов-кузнецов Калимдора.\r\n\r\nНа острове Зефрас не найти оружия лучше моего.','Приветствую тебя, |3-6($c). Тебе нужно оружие?\r\n\r\nМоим наставником был Антарион из Бан\'этала, и он обучил меня древним тайнам магов-кузнецов Калимдора.\r\n\r\nНа острове Зефрас не найти оружия лучше моего.',70338),
(321422,'ruRU','Ты найдешь Лотелума Звездный Ветер на утесе с видом на водопад. Это на восточном краю города.','Ты найдешь Лотелума Звездный Ветер на утесе с видом на водопад. Это на восточном краю города.',70338),
(323922,'ruRU','Да, я тот самый знаменитый торговец, который великодушно прокормил... э-э, голодающих... детей?.. Подгорода во время недавней войны с Плетью. Это я – деловой гоблин-визионер и гений логистики, который лично вооружил ополчение и помог Темной Госпоже объединить целый народ вонючих трупов... то есть Отрекшихся.\r\n\r\nДа, это я. Гликс Ксиззикс. С радостью дам автограф. Не бесплатно, конечно.\r\n\r\nСпросишь, зачем я открыл тут парикмахерскую? Одно слово: диверсификация. Чем больше разных источников дохода, тем лучше!','',70338),
(324145,'ruRU','','Несколько лет назад летающие острова что-то вывело из равновесия, и они начали отдаляться друг от друга. Мало того – теперь большие фрагменты Зефриса и вовсе падают вниз. Трудно представить, что твой дом в один прекрасный день обрушится в бездну, но мы теперь вот так живем.',70338),
(324553,'ruRU','Быть может, мне стоит напомнить тебе, небовидица, что пролилась кровь Высшего ордена? Мы призовем виновных к ответу.','Быть может, мне стоит напомнить тебе, небовидица, что пролилась кровь Высшего ордена? Мы призовем виновных к ответу.',70338),
(324554,'ruRU','','Кто бы говорил, чароплет. А как же Ваятели ветра, которых убил ваш агент на нагорье? Кто ответит за них?',70338),
(324555,'ruRU','','Никто? Я так и думала. Скажи Элаадрину, что я до сих пор не собрала шаманов и не сбросила тебя и других шарлатанов с этого острова лишь из-за нынешнего кризиса.',70338),
(324556,'ruRU','Но, небовидица, это же...','Но, небовидица, это же...',70338),
(324561,'ruRU','Она смеет нам угрожать, после того как ее приспешники расправились с представителями ордена на нагорье?','',70338),
(324562,'ruRU','Даже не знаю, кто опаснее – ал\'акеты или эти проклятые небом Ваятели ветра! Что ж, ладно. Если она не намерена уладить этот конфликт цивилизованно, мы ответим ей, как только минует этот кризис.','',70338),
(324563,'ruRU','А пока осведоми наш народ. Пусть все остерегаются Ваятелей ветра. Не мы начали эту войну, но мы закончим ее, как только разберемся с сектантами.','',70338),
(324564,'ruRU','Будет сделано, верховный магистр!','',70338),
(324978,'ruRU','Чем я могу помочь?','',70425),
(326162,'ruRU','The Wind Spirits have left us. \r\n\r\nNow, only mindless echoes remain. Be wary, however. These winds are neither kind, nor gentle.','The Wind Spirits have left us. \r\n\r\nNow, only mindless echoes remain. Be wary, however. These winds are neither kind, nor gentle.',70338),
(326948,'ruRU','Я Беланаа Вуаль Ветра, представитель Высшего ордена на Азероте. Буду признательна, если пожертвуешь немного ткани для нашей организации.','Я Беланаа Вуаль Ветра, представитель Высшего ордена на Азероте. Буду признательна, если пожертвуешь немного ткани для нашей организации.',70425),
(326965,'ruRU','Нас теперь совсем мало, но среди шен\'дорай еще остались изумрудные сновидцы.','',70338),
(327145,'ruRU','Отсюда идет корабль до Даларана в Альтеракские горы.','',70425),
(327146,'ruRU','Неборез возит пассажиров от этой пристани до Даларана.','',70425),
(328028,'ruRU','<The strider stills its agitated movements and fixes you with its golden eyes.>','',70338),
(328030,'ruRU','<The strider taps its talons on the moist soil.>','',70338),
(328033,'ruRU','<The strider preens its feathers and looks at you quizzically.>','',70338),
(328288,'ruRU','Если хочешь подстричь гриву, загляни на нижний уступ напротив аукционистов.','Если хочешь подстричь гриву, загляни на нижний уступ напротив аукционистов.',70425);
UPDATE `broadcast_text_locale` SET `Text_lang` = 'С одобрения Вариматраса ряды стражей смерти растут. Все больше клинков готовы ударить по нашим врагам, когда они будут меньше всего ожидать этого.', `Text1_lang` = 'С одобрения Вариматраса ряды стражей смерти растут. Все больше клинков готовы ударить по нашим врагам, когда они будут меньше всего ожидать этого.' WHERE `ID` = 2546 AND `locale` = 'ruRU' AND (NOT (CAST(`Text_lang` AS BINARY) <=> CAST('С одобрения Вариматраса ряды стражей смерти растут. Все больше клинков готовы ударить по нашим врагам, когда они будут меньше всего ожидать этого.' AS BINARY)) OR NOT (CAST(`Text1_lang` AS BINARY) <=> CAST('С одобрения Вариматраса ряды стражей смерти растут. Все больше клинков готовы ударить по нашим врагам, когда они будут меньше всего ожидать этого.' AS BINARY)));
UPDATE `broadcast_text_locale` SET `Text_lang` = 'Наралекс вновь спит!$b$bДавным-давно Наралекс отправился в эту пещеру с благородной целью: войти в Изумрудный Сон и превратить Степи в пышный лес. Его сосредоточенность была нарушена, и демонические видения опутали его разум.$b$bТеперь чудовища из его сна пробиваются в мир. Необходимо пробудить его от кошмаров, иначе он навеки затеряется в них, а великое зло вырвется из его сновидений на свободу.$b$bНо начать ритуал пробуждения я смогу не раньше, чем буду уничтожены его приспешники – повелители Змей.' WHERE `ID` = 2660 AND `locale` = 'ruRU' AND (NOT (CAST(`Text_lang` AS BINARY) <=> CAST('Наралекс вновь спит!$b$bДавным-давно Наралекс отправился в эту пещеру с благородной целью: войти в Изумрудный Сон и превратить Степи в пышный лес. Его сосредоточенность была нарушена, и демонические видения опутали его разум.$b$bТеперь чудовища из его сна пробиваются в мир. Необходимо пробудить его от кошмаров, иначе он навеки затеряется в них, а великое зло вырвется из его сновидений на свободу.$b$bНо начать ритуал пробуждения я смогу не раньше, чем буду уничтожены его приспешники – повелители Змей.' AS BINARY)));
UPDATE `broadcast_text_locale` SET `Text_lang` = 'Заходи, заходи. Только не садись слишком близко к печи. Она еще не взорвалась за сегодня, но безопасности ради лучше еще куда-нибудь сядь.', `Text1_lang` = 'Заходи, заходи. Только не садись слишком близко к печи. Она еще не взорвалась за сегодня, но безопасности ради лучше еще куда-нибудь сядь.' WHERE `ID` = 2828 AND `locale` = 'ruRU' AND (NOT (CAST(`Text_lang` AS BINARY) <=> CAST('Заходи, заходи. Только не садись слишком близко к печи. Она еще не взорвалась за сегодня, но безопасности ради лучше еще куда-нибудь сядь.' AS BINARY)) OR NOT (CAST(`Text1_lang` AS BINARY) <=> CAST('Заходи, заходи. Только не садись слишком близко к печи. Она еще не взорвалась за сегодня, но безопасности ради лучше еще куда-нибудь сядь.' AS BINARY)));
UPDATE `broadcast_text_locale` SET `Text_lang` = 'Чего желаете?', `Text1_lang` = 'Чего желаете?' WHERE `ID` = 4857 AND `locale` = 'ruRU' AND (NOT (CAST(`Text_lang` AS BINARY) <=> CAST('Чего желаете?' AS BINARY)) OR NOT (CAST(`Text1_lang` AS BINARY) <=> CAST('Чего желаете?' AS BINARY)));
UPDATE `broadcast_text_locale` SET `Text_lang` = 'Трактир? А, так ты хочешь отведать лучшего эля в Стальгорне? Ну, тогда тебе надо в "Горючий камень".$B$BЕсли идти из ворот Стальгорна, он будет слева, а если к воротам – справа.', `Text1_lang` = 'Трактир? А, так ты хочешь отведать лучшего эля в Стальгорне? Ну, тогда тебе надо в "Горючий камень".$B$BЕсли идти из ворот Стальгорна, он будет слева, а если к воротам – справа.' WHERE `ID` = 5091 AND `locale` = 'ruRU' AND (NOT (CAST(`Text_lang` AS BINARY) <=> CAST('Трактир? А, так ты хочешь отведать лучшего эля в Стальгорне? Ну, тогда тебе надо в "Горючий камень".$B$BЕсли идти из ворот Стальгорна, он будет слева, а если к воротам – справа.' AS BINARY)) OR NOT (CAST(`Text1_lang` AS BINARY) <=> CAST('Трактир? А, так ты хочешь отведать лучшего эля в Стальгорне? Ну, тогда тебе надо в "Горючий камень".$B$BЕсли идти из ворот Стальгорна, он будет слева, а если к воротам – справа.' AS BINARY)));
