UPDATE `broadcast_text_locale` SET `Text_lang` = '$gПривет, красавчик! Хочешь прокатиться в Гром\'гол? Там, внизу, в джунглях, говорят, жарковато… А я бы тебе даже компанию составил, настоящего камышового кота показал…:Эй, красавица, хочешь побывать в чудесных, роскошных тропических джунглях Тернистой долины? Позагорать на берегу кристально чистых озер, пока я тут парюсь на жаре в компании своего брата Фреззы? В общем, приятного полета!;', `Text1_lang` = '$gПривет, красавчик! Хочешь прокатиться в Гром\'гол? Там внизу, в джунглях, говорят, жарковато… А я бы тебе даже компанию составила, настоящего камышового кота показала…:Эй, красавица, хочешь побывать в чудесных, роскошных тропических джунглях Тернистой долины? Позагорать на берегу кристально чистых озер, пока я тут парюсь на жаре в компании своего брата Фреззы? В общем, приятного полета!;' WHERE `ID` = 7376 AND `locale` = 'ruRU' AND (NOT (CAST(`Text_lang` AS BINARY) <=> CAST('$gПривет, красавчик! Хочешь прокатиться в Гром\'гол? Там, внизу, в джунглях, говорят, жарковато… А я бы тебе даже компанию составил, настоящего камышового кота показал…:Эй, красавица, хочешь побывать в чудесных, роскошных тропических джунглях Тернистой долины? Позагорать на берегу кристально чистых озер, пока я тут парюсь на жаре в компании своего брата Фреззы? В общем, приятного полета!;' AS BINARY)) OR NOT (CAST(`Text1_lang` AS BINARY) <=> CAST('$gПривет, красавчик! Хочешь прокатиться в Гром\'гол? Там внизу, в джунглях, говорят, жарковато… А я бы тебе даже компанию составила, настоящего камышового кота показала…:Эй, красавица, хочешь побывать в чудесных, роскошных тропических джунглях Тернистой долины? Позагорать на берегу кристально чистых озер, пока я тут парюсь на жаре в компании своего брата Фреззы? В общем, приятного полета!;' AS BINARY)));
UPDATE `broadcast_text_locale` SET `Text1_lang` = 'Добро пожаловать, $gбрат:сестра;. Если ты $gпришел:пришла; учиться, я с радостью поделюсь с тобой знаниями.$B$BВскоре ты погрузишься в Изумрудный Сон. Ты проспишь долгие годы и примешь множество обличий. Именно так будет проходить твое обучение.' WHERE `ID` = 7461 AND `locale` = 'ruRU' AND (NOT (CAST(`Text1_lang` AS BINARY) <=> CAST('Добро пожаловать, $gбрат:сестра;. Если ты $gпришел:пришла; учиться, я с радостью поделюсь с тобой знаниями.$B$BВскоре ты погрузишься в Изумрудный Сон. Ты проспишь долгие годы и примешь множество обличий. Именно так будет проходить твое обучение.' AS BINARY)));
UPDATE `broadcast_text_locale` SET `Text_lang` = 'Эй! Ты крепко $gсложен:сложена;, а у нас тут стражей не хватает. Нам бы не помешала твоя помощь…' WHERE `ID` = 7590 AND `locale` = 'ruRU' AND (NOT (CAST(`Text_lang` AS BINARY) <=> CAST('Эй! Ты крепко $gсложен:сложена;, а у нас тут стражей не хватает. Нам бы не помешала твоя помощь…' AS BINARY)));
UPDATE `broadcast_text_locale` SET `Text1_lang` = '' WHERE `ID` = 7654 AND `locale` = 'ruRU' AND (NOT (CAST(`Text1_lang` AS BINARY) <=> CAST('' AS BINARY)));
UPDATE `broadcast_text_locale` SET `Text_lang` = 'Когда-нибудь ты сможешь у меня поучиться, но не сейчас! Почему бы тебе не поговорить со Спрайт Прыгозубчик? Она стоит справа от меня. А ко мне приходи, когда опыта наберешься!' WHERE `ID` = 7834 AND `locale` = 'ruRU' AND (NOT (CAST(`Text_lang` AS BINARY) <=> CAST('Когда-нибудь ты сможешь у меня поучиться, но не сейчас! Почему бы тебе не поговорить со Спрайт Прыгозубчик? Она стоит справа от меня. А ко мне приходи, когда опыта наберешься!' AS BINARY)));
UPDATE `broadcast_text_locale` SET `Text_lang` = 'Если бы в сутках была еще пара лишних часов…' WHERE `ID` = 7841 AND `locale` = 'ruRU' AND (NOT (CAST(`Text_lang` AS BINARY) <=> CAST('Если бы в сутках была еще пара лишних часов…' AS BINARY)));
UPDATE `broadcast_text_locale` SET `Text_lang` = 'Может, у гномов Громового Молота и быстрокрылые скакуны, но могут ли грифоны Заоблачного Пика выдержать жар Великой Кузни? Навряд ли!' WHERE `ID` = 8217 AND `locale` = 'ruRU' AND (NOT (CAST(`Text_lang` AS BINARY) <=> CAST('Может, у гномов Громового Молота и быстрокрылые скакуны, но могут ли грифоны Заоблачного Пика выдержать жар Великой Кузни? Навряд ли!' AS BINARY)));
UPDATE `broadcast_text_locale` SET `Text_lang` = 'Достаточно бросить на тебя один взгляд, чтобы понять, что ты не воин.$B$BМожет пойдешь позанимаешься чем-нибудь безопасным? Книжку там почитаешь…', `Text1_lang` = 'Достаточно бросить на тебя один взгляд, чтобы понять, что ты не воин.$B$BМожет пойдешь позанимаешься чем-нибудь безопасным? Книжку там почитаешь…' WHERE `ID` = 8299 AND `locale` = 'ruRU' AND (NOT (CAST(`Text_lang` AS BINARY) <=> CAST('Достаточно бросить на тебя один взгляд, чтобы понять, что ты не воин.$B$BМожет пойдешь позанимаешься чем-нибудь безопасным? Книжку там почитаешь…' AS BINARY)) OR NOT (CAST(`Text1_lang` AS BINARY) <=> CAST('Достаточно бросить на тебя один взгляд, чтобы понять, что ты не воин.$B$BМожет пойдешь позанимаешься чем-нибудь безопасным? Книжку там почитаешь…' AS BINARY)));
UPDATE `broadcast_text_locale` SET `Text_lang` = 'Рыбка такая вкусная. Ты хочешь учиться ловить рыбку? Есть рыбку? Мммммм…' WHERE `ID` = 8334 AND `locale` = 'ruRU' AND (NOT (CAST(`Text_lang` AS BINARY) <=> CAST('Рыбка такая вкусная. Ты хочешь учиться ловить рыбку? Есть рыбку? Мммммм…' AS BINARY)));
UPDATE `broadcast_text_locale` SET `Text_lang` = 'Чтобы начать обучение, тебе необходимо завоевать полное доверие орков Оргриммара, |3-6($c).', `Text1_lang` = 'Чтобы начать обучение, тебе необходимо завоевать полное доверие орков Оргриммара, |3-6($c).' WHERE `ID` = 8436 AND `locale` = 'ruRU' AND (NOT (CAST(`Text_lang` AS BINARY) <=> CAST('Чтобы начать обучение, тебе необходимо завоевать полное доверие орков Оргриммара, |3-6($c).' AS BINARY)) OR NOT (CAST(`Text1_lang` AS BINARY) <=> CAST('Чтобы начать обучение, тебе необходимо завоевать полное доверие орков Оргриммара, |3-6($c).' AS BINARY)));
UPDATE `broadcast_text_locale` SET `Text1_lang` = 'Между светом и тьмой есть тень… И эти тени обладают силой, которую ты еще не видишь.' WHERE `ID` = 8473 AND `locale` = 'ruRU' AND (NOT (CAST(`Text1_lang` AS BINARY) <=> CAST('Между светом и тьмой есть тень… И эти тени обладают силой, которую ты еще не видишь.' AS BINARY)));
UPDATE `broadcast_text_locale` SET `Text_lang` = 'Сайок, орочий эксперт по оружию, живет на Аллее Чести в Оргриммаре. Он обучает владению луками, кинжалами, кистевым и метательным оружием, а еще одноручными и двуручными топорами.\r\n\r\nТролль Ханаши обитает там же. Он покажет тебе, как пользоваться одноручными и двуручными топорами, посохами и всем возможным метательным оружием.\r\n\r\nАнсеква, тауренский эксперт по оружию, трудится на нижнем ярусе Громового Утеса. Он обучает владению двуручными булавами, посохами и огнестрельным оружием.' WHERE `ID` = 8874 AND `locale` = 'ruRU' AND (NOT (CAST(`Text_lang` AS BINARY) <=> CAST('Сайок, орочий эксперт по оружию, живет на Аллее Чести в Оргриммаре. Он обучает владению луками, кинжалами, кистевым и метательным оружием, а еще одноручными и двуручными топорами.\r\n\r\nТролль Ханаши обитает там же. Он покажет тебе, как пользоваться одноручными и двуручными топорами, посохами и всем возможным метательным оружием.\r\n\r\nАнсеква, тауренский эксперт по оружию, трудится на нижнем ярусе Громового Утеса. Он обучает владению двуручными булавами, посохами и огнестрельным оружием.' AS BINARY)));
UPDATE `broadcast_text_locale` SET `Text_lang` = 'Приветствую тебя, $gгерой:героиня;! Я принес последние новости с обоих континентов и даже из-за их пределов.', `Text1_lang` = 'Приветствую тебя, $gгерой:героиня;! Я принесла последние новости с обоих континентов и даже из-за их пределов.' WHERE `ID` = 9551 AND `locale` = 'ruRU' AND (NOT (CAST(`Text_lang` AS BINARY) <=> CAST('Приветствую тебя, $gгерой:героиня;! Я принес последние новости с обоих континентов и даже из-за их пределов.' AS BINARY)) OR NOT (CAST(`Text1_lang` AS BINARY) <=> CAST('Приветствую тебя, $gгерой:героиня;! Я принесла последние новости с обоих континентов и даже из-за их пределов.' AS BINARY)));
UPDATE `broadcast_text_locale` SET `Text1_lang` = 'Любая война приносит потери, |3-6($c)… Потери, о которых часто забывают. Вот, например, сироты, потерявшие родителей в бесчисленных битвах Азерота. Эти дети, которым некуда больше пойти, часто приходят сюда жить и остаются с нами, пока не вырастут.$B$BОдну неделю в году, весной, Орда находит время, чтобы хоть как-то искупить их страдания. Это время зовется Детской неделей.' WHERE `ID` = 9656 AND `locale` = 'ruRU' AND (NOT (CAST(`Text1_lang` AS BINARY) <=> CAST('Любая война приносит потери, |3-6($c)… Потери, о которых часто забывают. Вот, например, сироты, потерявшие родителей в бесчисленных битвах Азерота. Эти дети, которым некуда больше пойти, часто приходят сюда жить и остаются с нами, пока не вырастут.$B$BОдну неделю в году, весной, Орда находит время, чтобы хоть как-то искупить их страдания. Это время зовется Детской неделей.' AS BINARY)));
UPDATE `broadcast_text_locale` SET `Text_lang` = 'Я могу научить тебя оказывать первую помощь.', `Text1_lang` = 'Я могу научить тебя оказывать первую помощь.' WHERE `ID` = 9701 AND `locale` = 'ruRU' AND (NOT (CAST(`Text_lang` AS BINARY) <=> CAST('Я могу научить тебя оказывать первую помощь.' AS BINARY)) OR NOT (CAST(`Text1_lang` AS BINARY) <=> CAST('Я могу научить тебя оказывать первую помощь.' AS BINARY)));
UPDATE `broadcast_text_locale` SET `Text_lang` = 'Эй, ты… Заруби себе на носу: помогать Отрекшимся в такие страшные времена – в твоих же интересах. А теперь слушай внимательно – повторять я не люблю.$B$BУ нас сейчас жуткий дефицит ткани. Бинты и другие тканные материалы почти закончились. Чтобы пополнить иссякшие запасы, мы принимаем ткани безвозмездно – то есть даром. Очевидно, денег ты за это не получишь, но твое участие не останется незамеченным.' WHERE `ID` = 9893 AND `locale` = 'ruRU' AND (NOT (CAST(`Text_lang` AS BINARY) <=> CAST('Эй, ты… Заруби себе на носу: помогать Отрекшимся в такие страшные времена – в твоих же интересах. А теперь слушай внимательно – повторять я не люблю.$B$BУ нас сейчас жуткий дефицит ткани. Бинты и другие тканные материалы почти закончились. Чтобы пополнить иссякшие запасы, мы принимаем ткани безвозмездно – то есть даром. Очевидно, денег ты за это не получишь, но твое участие не останется незамеченным.' AS BINARY)));
UPDATE `broadcast_text_locale` SET `Text_lang` = 'Тром\'ка, |3-6($c)! $gГотов:Готова; ли ты сражаться за Орду в Ущелье Песни Войны?' WHERE `ID` = 10520 AND `locale` = 'ruRU' AND (NOT (CAST(`Text_lang` AS BINARY) <=> CAST('Тром\'ка, |3-6($c)! $gГотов:Готова; ли ты сражаться за Орду в Ущелье Песни Войны?' AS BINARY)));
UPDATE `broadcast_text_locale` SET `Text1_lang` = 'Люди и их так называемая Лига Аратора хотят выгнать нас из Низины Арати. Еще чего! |3-6($c), ты $gготов:готова; отправиться туда и продемонстрировать, что это они, а не Осквернители, должны убраться оттуда?' WHERE `ID` = 10531 AND `locale` = 'ruRU' AND (NOT (CAST(`Text1_lang` AS BINARY) <=> CAST('Люди и их так называемая Лига Аратора хотят выгнать нас из Низины Арати. Еще чего! |3-6($c), ты $gготов:готова; отправиться туда и продемонстрировать, что это они, а не Осквернители, должны убраться оттуда?' AS BINARY)));
UPDATE `broadcast_text_locale` SET `Text_lang` = 'Куда бы вы хотели слетать?', `Text1_lang` = 'Куда бы вы хотели слетать?' WHERE `ID` = 10753 AND `locale` = 'ruRU' AND (NOT (CAST(`Text_lang` AS BINARY) <=> CAST('Куда бы вы хотели слетать?' AS BINARY)) OR NOT (CAST(`Text1_lang` AS BINARY) <=> CAST('Куда бы вы хотели слетать?' AS BINARY)));

